// Part 6: Networking and SSH, units 51-58. See materials/curriculum.md and materials/objectives/.
// Output was recorded on a GitHub Actions Ubuntu 24.04 VM (tests/sandbox/record/vm-p6.txt). The lab there:
// the interface lab0 (192.168.50.1) connects to a lab server srv (192.168.50.10), which routes to db (10.0.60.20).
// p6Fixture() adds the network files from /etc and an ~/.ssh/config, so learners can read them with grep and cat.
function p6Fixture() {
  const fx = homeFixture();
  fx.dirs.push('/etc/ssh', '/home/user/.ssh');
  fx.files.push(
    ['/etc/hostname', { owner: 'root', content: 'web01\n' }],
    ['/etc/hosts', { owner: 'root', content: '127.0.0.1       localhost\n127.0.1.1       web01\n192.168.50.10   srv.lab.local srv\n10.0.60.20      db.lab.local db\n' }],
    ['/etc/resolv.conf', { owner: 'root', content: 'nameserver 127.0.0.53\noptions edns0 trust-ad\nsearch lab.local\n' }],
    ['/etc/nsswitch.conf', { owner: 'root', content: 'passwd:         files systemd\ngroup:          files systemd\nhosts:          files dns\nservices:       files\n' }],
    ['/etc/services', { owner: 'root', content: 'ftp             21/tcp\nssh             22/tcp\nsmtp            25/tcp          mail\ndomain          53/tcp\ndomain          53/udp\nhttp            80/tcp          www\nntp             123/udp\nhttps           443/tcp\nhttps           443/udp\n' }],
    ['/etc/ssh/sshd_config', { owner: 'root', content: 'Port 22\nPermitRootLogin yes\nPasswordAuthentication yes\nPubkeyAuthentication yes\nX11Forwarding yes\n' }],
    ['/home/user/.ssh/config', { mode: 0o600, content: 'Host lab\n    HostName 192.168.50.10\n    User dana\n    Port 2222\n\nHost backup\n    HostName backup.example.com\n    User omer\n    IdentityFile ~/.ssh/id_ed25519\n' }],
  );
  return fx;
}
const p6Out = cmd => { const sh = new Shell(p6Fixture()); const r = sh.run(cmd); return r.out + r.err; };
const p6Shown = (log, cmd) => { const want = p6Out(cmd).trim(); return !!want && log.some(l => l.out.trim() === want); };
const P6_REC = T('הפלט הוקלט על שרת Ubuntu אמיתי. מה הודפס?', 'This was recorded on a real Ubuntu server. What was printed?');
// A wrong option made from a real recording with a few words swapped, so it looks just like the real thing.
const p6Alt = (id, ...pairs) => { let s = RECORDED[id].out; for (let i = 0; i < pairs.length; i += 2) s = s.split(pairs[i]).join(pairs[i + 1]); return s; };
const p6Sudo = cmds => cmds.flatMap(c => [c, `sudo ${c}`]);
const p6Perm = s => s.length <= 1 ? [s] : [...s].flatMap((c, i) => p6Perm(s.slice(0, i) + s.slice(i + 1)).map(r => c + r));
const p6Nm = (...cmds) => p6Sudo([...new Set(cmds.flatMap(c => { const out = [c]; for (const [a, b] of [[' con ', ' connection '], [' mod ', ' modify '], ["'", '"']]) out.push(...out.map(x => x.split(a).join(b))); return out; }))]);

